.panel {
  width: 340px;
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  background: var(--bw-warm-cream);
  border: 1px solid var(--bw-line-steel);
  border-radius: var(--bw-radius);
  overflow: hidden;
}

.header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px;
  padding: 14px 16px;
  background: var(--bw-surface-mist);
  border-bottom: 1px solid var(--bw-divider-mist);
}

.headerText {
  min-width: 0;
}

.eyebrow {
  margin: 0 0 3px;
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: var(--bw-ls-brand);
  color: var(--bw-brass);
}

.title {
  margin: 0;
